#Requires -Version 5.1
param([Parameter(Mandatory=$true)][string]$PythonExe,[Parameter(Mandatory=$true)][string]$InstallDirectory,[string]$KitDirectory="")
$ErrorActionPreference="Stop"; Set-StrictMode -Version Latest
if (!$KitDirectory) {$KitDirectory=$PSScriptRoot}; . (Join-Path $PSScriptRoot "analysis-kit-common.ps1")
$kit=Get-AnalysisFullPath $KitDirectory; $install=Get-AnalysisFullPath $InstallDirectory; if(Test-Path -LiteralPath $install){throw "InstallDirectory must be clean."}; $m=Test-AnalysisKit $kit
$probe=& $PythonExe -I -c "import platform,struct;print(platform.python_implementation(),platform.python_version(),struct.calcsize('P')*8)"; if($LASTEXITCODE -ne 0 -or $probe -ne "CPython 3.13.12 64"){throw "CPython 3.13.12 x64 is required."}
$parent=Split-Path -Parent $install; $stage=Join-Path $parent (".analysis-env-"+[guid]::NewGuid().ToString("N")); try {New-Item -ItemType Directory -Path $stage|Out-Null; & $PythonExe -I -m venv (Join-Path $stage '.venv'); $py=Join-Path $stage '.venv\Scripts\python.exe'; & $py -I -m pip install --no-index --only-binary=:all: --require-hashes --find-links (Join-Path $kit 'wheels') -r (Join-Path $kit $m.dependency_lock); if($LASTEXITCODE -ne 0){throw "offline wheel installation failed"}; Expand-Archive -LiteralPath (Get-ChildItem (Join-Path $kit 'source') -Filter *.zip -File).FullName -DestinationPath (Join-Path $stage 'source'); Copy-Item (Join-Path $kit 'sites') (Join-Path $stage 'sites') -Recurse; Write-AnalysisUtf8 (Join-Path $stage 'source-commit.txt') ($m.source_commit+"`n"); Move-Item $stage $install; @{status='installed';offline=$true}|ConvertTo-Json -Compress } catch {if(Test-Path $stage){Remove-Item $stage -Recurse -Force};throw}
